import { policyDepartments,validateDepartmentScope } from '../shared/policyDepartmentScope.mjs';
import { validateCompanyPolicyProfile,parsePolicyPlan,POLICY_SECTIONS } from '../shared/companyPolicyProfile.mjs';
import { asterTask } from './groq.mjs';
const compactProfile=profile=>Object.fromEntries(Object.entries(profile).map(([key,value])=>[key,String(value).slice(0,600)]));
const fail=(text,status=400)=>{throw Object.assign(new Error(text),{status});};
const first=async(db,company,collection)=>(await db.prepare('SELECT payload FROM talent_records WHERE company_id=? AND collection=? AND id=?').bind(company,collection,`${company}:${collection}`).first());
const read=async(db,company,collection)=>{const row=await first(db,company,collection);return row?JSON.parse(row.payload):null;};
const write=async(db,company,collection,value)=>db.prepare("INSERT INTO talent_records(company_id,collection,id,payload,created_at,updated_at) VALUES(?,?,?,?,datetime('now'),datetime('now')) ON CONFLICT(company_id,collection,id) DO UPDATE SET payload=excluded.payload,revision=talent_records.revision+1,updated_at=datetime('now')").bind(company,collection,`${company}:${collection}`,JSON.stringify(value)).run();
export async function companyPolicyHandle({db,env,actor,section,method,body,internal=false}) {
 const company=actor.company_id;
 if(['policy-run','policy-pause'].includes(section)&&method==='POST'){if(!env.POLICY_GENERATION)fail('Background policy generation is unavailable.',503);const response=await env.POLICY_GENERATION.get(env.POLICY_GENERATION.idFromName(company)).fetch('https://policy-runner.internal',{method:'POST',body:JSON.stringify({actor,jobId:body.jobId,action:section==='policy-run'?'start':'pause'})});const result=await response.json();if(!response.ok)fail(result.error||'Unable to update background generation.',response.status);return result;}
 if(section==='policy-departments'&&method==='GET')return policyDepartments(db,company);
 if(section==='company-profile'&&method==='GET'){const profile=await read(db,company,'company_policy_profile');if(profile)return profile;const row=await db.prepare('SELECT name FROM companies WHERE company_id=?').bind(company).first();return {legal_name:row?.name||''};}
 if(section==='company-profile'&&method==='POST'){let profile;try{profile=validateCompanyPolicyProfile(body);}catch(error){fail(error.message);}await write(db,company,'company_policy_profile',profile);return profile;}
 if(section==='policy-job'&&method==='GET') { const job=await read(db,company,'company_policy_job');if(!job)return null;let changed=false;for(const item of job.items){if(item.sections.length!==POLICY_SECTIONS.length)continue;const saved=await db.prepare("SELECT document_id FROM documents WHERE company_id=? AND employee_id IS NULL AND json_extract(metadata,'$.generation_job')=? AND json_extract(metadata,'$.generation_item')=? AND json_extract(metadata,'$.deleted_at') IS NULL LIMIT 1").bind(company,job.id,item.id).first();const id=saved?.document_id||null;if(item.savedId!==id){item.savedId=id;item.status=id?'saved':'ready';changed=true;}}if(job.runState==='complete'&&job.items.some(item=>!item.savedId)){job.runState='paused';job.phase='Some drafts are missing. Generate / resume to finish.';changed=true;}if(changed)await write(db,company,'company_policy_job',job);return job; }
 if(section==='policy-plan'&&method==='POST'){
  const previous=await read(db,company,'company_policy_job');if(['queued','generating','waiting','saving'].includes(previous?.runState))fail('Pause background generation before replacing the plan.',409);if(previous&&previous.items.some(item=>!item.savedId)&&body.replace!==true)fail('Resume the current plan, or explicitly replace it.');
  let profile;try{profile=validateCompanyPolicyProfile(await read(db,company,'company_policy_profile'));}catch{fail('Complete Company policy profile in Settings before generating documents.');}
  let departments;try{departments=validateDepartmentScope(body.departments||[],await policyDepartments(db,company));}catch(error){fail(error.message);}
  const result=await asterTask({env,actor,page:'documents',body:{action:'draft',prompt:'Suggest 5 to 8 relevant internal company policy documents based only on this company profile. Avoid duplicate topics. Text must contain ONLY lines in this exact format: Document title | Category name | Why this company needs this document. No table header, no Markdown table separators. Maximum 10 lines, each title <=200, category <=100 and purpose <=500 characters. These are proposed internal policies, not claims of statutory obligations.',context:JSON.stringify({company_profile:compactProfile(profile),applicable_departments:departments.length?departments:'All departments',scope_instruction:'Suggest documents applicable only to the selected departments. For all departments use company-wide policies.'})}});
  let items;try{items=parsePolicyPlan(result.text);}catch(error){fail(error.message,502);}if(items.length<5||items.length>8)fail('Aster returned an incomplete plan. Suggest documents again; your existing plan is retained.',502);const job={id:crypto.randomUUID(),profile,departments,createdAt:new Date().toISOString(),items};await write(db,company,'company_policy_job',job);return job;
 }
 if(section==='policy-section'&&method==='POST'){
  const job=await read(db,company,'company_policy_job');if(!internal&&['queued','generating','waiting','saving'].includes(job?.runState))fail('This plan is being generated in the background.',409);if(!job||job.id!==body.jobId)fail('Policy plan changed. Reload the plan.',409);const item=job.items.find(item=>item.id===body.itemId);if(!item)fail('Policy not found.',404);if(item.savedId||item.sections.length>=POLICY_SECTIONS.length)return job;
  const sectionIndex=item.sections.length;
  if(body.sectionIndex!==sectionIndex)return job;
  const context=JSON.stringify({company_profile:compactProfile(job.profile),applicable_departments:job.departments?.length?job.departments:'All departments',scope_instruction:'Apply this document only to these departments. Clearly state applicability.',document_title:item.title,category:item.category,purpose:item.purpose,section:POLICY_SECTIONS[sectionIndex],previous_section_summaries:item.sections.map(section=>section.text.slice(0,1000)),draft:true});
  const result=await asterTask({env,actor,page:'documents',body:{action:'draft',prompt:`Write ONLY section ${sectionIndex+1}: ${POLICY_SECTIONS[sectionIndex]} of the proposed internal company policy. Write 350-500 words with useful subheadings, responsibilities and practical details; maximum 7000 characters. Do not repeat the title, letter salutation, other sections or a signature. Tailor it to the company profile. Label any unknown fact with a specific [Field required]. Proposed rules not supplied by the company must be explicitly marked for HR approval. Do not assert legal compliance, invent laws, rates or legal deadlines. Any legal requirement needs qualified local review. Return the normal title/text/letter_type JSON; letter_type is company-policy.`,context}});
  const fresh=await read(db,company,'company_policy_job');if(!fresh||fresh.id!==job.id)fail('Policy plan changed while generating. Reload.',409);const target=fresh.items.find(entry=>entry.id===item.id);if(target.sections.length!==sectionIndex)return fresh;
  target.sections.push({heading:POLICY_SECTIONS[sectionIndex],text:result.text.slice(0,7000)});target.status=target.sections.length===POLICY_SECTIONS.length?'ready':'generating';await write(db,company,'company_policy_job',fresh);return fresh;
 }
 if(section==='policy-saved'&&method==='POST'){
  const job=await read(db,company,'company_policy_job');if(!job||job.id!==body.jobId)fail('Policy plan changed.',409);const item=job.items.find(item=>item.id===body.itemId);if(!item||item.sections.length!==POLICY_SECTIONS.length)fail('Complete the document before saving.');
  const document=await db.prepare("SELECT document_id FROM documents WHERE company_id=? AND document_id=? AND employee_id IS NULL AND json_extract(metadata,'$.origin')='ai' AND json_extract(metadata,'$.generation_job')=? AND json_extract(metadata,'$.generation_item')=? AND json_extract(metadata,'$.deleted_at') IS NULL").bind(company,body.documentId,job.id,item.id).first();if(!document)fail('Saved AI draft not found for this plan item.',404);item.savedId=document.document_id;item.status='saved';await write(db,company,'company_policy_job',job);return job;
 }
 fail('Policy assistant route not found.',404);
}
