export const departmentAllowed=(scope,department)=>!Array.isArray(scope)||scope.length===0||scope.includes(department);
export function validateDepartmentScope(value,available){if(!Array.isArray(value)||value.length>50||value.some(name=>typeof name!=='string'||!available.includes(name)))throw Error('Select valid departments from this company.');return [...new Set(value)];}
export async function policyDepartments(db,company){const [people,config]=await Promise.all([db.prepare("SELECT DISTINCT department FROM employees WHERE company_id=? AND department IS NOT NULL AND department!=''").bind(company).all(),db.prepare('SELECT payload FROM workflow_configuration WHERE company_id=?').bind(company).first()]);let saved=[];try{saved=JSON.parse(config?.payload||'{}').departments||[];}catch{}return [...new Set([...(people.results||[]).map(person=>person.department),...saved.map(department=>department.name)].filter(Boolean))].sort();}
